公開操作 updateNote(store, id, note, retryKey, consumed) を追加する。引数は検証・認可済みの通常の値、noteはstring、consumedはSet。既消費retryKeyは409、対象未存在は404。store.getはlive record参照を返す。store.save(id, record) は同期で、成功時に保存、失敗時はthrowし保存しない。save失敗は503で、読み出せるrecord状態を変更せずretryKeyも消費しない。成功時のみnoteの更新とretryKey消費を行い200。並行実行・クラッシュ・外部I/Oは対象外。
// 新規操作。変更前はこのmoduleを提供していない。
export function updateNote(store, id, note, retryKey, consumed) {
  if (consumed.has(retryKey)) return { status: 409 };
  const record = store.get(id);
  if (!record) return { status: 404 };
  consumed.add(retryKey);
  record.note = note;
  try { store.save(id, record); }
  catch { return { status: 503 }; }
  return { status: 200 };
}
