/bin/bash -lc "node --input-type=module <<'JS'
import assert from 'node:assert/strict';
import { updateNote } from './subject.mjs';
const live = {note:'old', other:42};
const records = new Map([['x',live]]);
let fail = true;
let saves = 0;
const store = {get:id=>records.get(id), save(id,record) { saves++; if(fail) throw new Error('save failed'); records.set(id,record); }};
const consumed = new Set();
const failure = updateNote(store,'x','new','k',consumed);
assert.equal(failure.status,503);
console.log(JSON.stringify({scenario:'save failure',status:failure.status,readableRecord:store.get('x'),sameLiveReference:store.get('x')===live,retryKeyConsumed:consumed.has('k'),saves}));
fail=false;
const retry=updateNote(store,'x','new','k',consumed);
console.log(JSON.stringify({scenario:'retry after failure',status:retry.status,saves}));
assert.equal(retry.status,409);
const missing=updateNote(store,'missing','new','m',consumed);
assert.equal(missing.status,404);
assert.equal(consumed.has('m'),false);
assert.equal(saves,1);
const success=updateNote(store,'x','ok','fresh',consumed);
assert.equal(success.status,200);
assert.equal(store.get('x').note,'ok');
assert.equal(store.get('x').other,42);
assert.equal(consumed.has('fresh'),true);
const duplicate=updateNote(store,'x','ignored','fresh',consumed);
assert.equal(duplicate.status,409);
assert.equal(store.get('x').note,'ok');
assert.equal(saves,2);
console.log('normal, duplicate, missing, failure and retry paths checked');
JS"

